import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import {assertMidiNotes} from '@/components/nyc-tron/ui/components/forge/midi/note-grid';
import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import { Pressable, ScrollView, Text, View, type KeyDownEvent, type ViewProps } from "react-native";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { webToggleProps } from "@/components/nyc-tron/ui/components/forge/toggle-a11y";
import { stepCells, type MidiNote, type StepLane } from "@/components/nyc-tron/ui/components/forge/midi/note-grid";
import { space, radius, opacity } from '@/components/nyc-tron/ui/tokens';

const HIT = 44;
const NAME_COLUMN = 72;

/** Props for {@linkcode StepSequencer}. */
export interface StepSequencerProps extends Omit<ViewProps, "children">,ScopedControlProps {
  /** Committed notes of the clip the grid edits. */
  readonly notes: readonly MidiNote[];
  /** One row per instrument, top to bottom. */
  readonly lanes: readonly StepLane[];
  /** Clip length, ticks. `steps * stepTicks` must fit. */
  readonly clipTicks: number;
  /** @default 16 */
  readonly steps?: number;
  /** Ticks per step. @default 240 (a sixteenth at 960 ppq) */
  readonly stepTicks?: number;
  /** Steps per beat group, for shading. @default 4 */
  readonly stepsPerBeat?: number;
  /** Velocity of a new step. @default 96 */
  readonly velocity?: number;
  /** Velocity of an accented step; a step at or above it shows as accented. @default 127 */
  readonly accentVelocity?: number;
  /** Step under the playhead while playing. */
  readonly currentStep?: number;
  /** Turn an empty step on. */
  readonly onStepAdd: (pitch: number, startTicks: number, lengthTicks: number, velocity: number) => void | Promise<unknown>;
  /** Turn a step off. `noteIndex` is the engine's note index. */
  readonly onStepRemove: (noteIndex: number) => void | Promise<unknown>;
  /** Accent or un-accent a step (long press, the A key, or the screen-reader action). */
  readonly onStepVelocity: (noteIndex: number, velocity: number) => void | Promise<unknown>;
  /** @default false */
  readonly disabled?: boolean;
  /** @default "Step sequencer" */
  readonly label?: string;
  className?: string;
  unstyled?: boolean;
}

/**
 * Controlled beat grid over one clip's notes. A step is a note of the
 * lane's pitch starting on that step. Press toggles a step, long press or A
 * toggles its accent. Each press is one commit.
 *
 * Steps run left to right in every locale, like the piano roll. Lanes are
 * pitches, so a drum map is the app's `lanes` list.
 */
export function StepSequencer({scope='StepSequencer',revision=0,...props}:StepSequencerProps){
 assertMidiNotes(props.notes,props.clipTicks);
 const owner=JSON.stringify([...controlIdentity(scope,revision),props.clipTicks,props.steps,props.stepTicks,props.lanes,props.notes,props.disabled,props.disabledReason]),guard=useScopedControl(owner,props,!!props.disabled||props.disabledReason!==undefined);
 return <StepSequencerBody key={owner} {...props} actionError={guard.error} disabled={!!props.disabled||props.disabledReason!==undefined||guard.pending}
  onStepAdd={(...args:Parameters<StepSequencerProps['onStepAdd']>)=>guard.run('onStepAdd',h=>h.onStepAdd(...args))}
  onStepRemove={(...args:Parameters<StepSequencerProps['onStepRemove']>)=>guard.run('onStepRemove',h=>h.onStepRemove(...args))}
  onStepVelocity={(...args:Parameters<StepSequencerProps['onStepVelocity']>)=>guard.run('onStepVelocity',h=>h.onStepVelocity(...args))}
 />;
}
function StepSequencerBody({actionError,disabledReason,
  notes, lanes, clipTicks, steps = 16, stepTicks = 240, stepsPerBeat = 4, velocity = 96, accentVelocity = 127,
  currentStep, onStepAdd, onStepRemove, onStepVelocity, disabled = false, label = "Step sequencer",
  className, unstyled = false, ...rest
}: StepSequencerProps&{actionError?:string|null}) {
  if (!Number.isInteger(clipTicks) || steps * stepTicks > clipTicks) {
    throw new RangeError("steps * stepTicks must fit inside clipTicks");
  }
  if (!(velocity < accentVelocity)) throw new RangeError("velocity must be below accentVelocity");
  const styled = !unstyled;
  const cells = stepCells(notes, lanes, steps, stepTicks, accentVelocity);
  const toggleAccent = (noteIndex: number, accent: boolean) => {
    if (!disabled) void onStepVelocity(noteIndex, accent ? velocity : accentVelocity);
  };
  return <View {...rest} accessibilityLabel={label} {...{ role: "group" }}
    {...{ className: joinClasses(styled && "rounded-card border border-border bg-surface-raised", className) }}>
    <View style={{ flexDirection: "row", direction: "ltr" }}>
      <View style={{ width: NAME_COLUMN, paddingTop: space[1], gap: space[1] }}>
        {lanes.map(lane => <View key={lane.pitch} style={{ height: HIT, justifyContent: "center", paddingHorizontal: space[2] }}>
          <Text numberOfLines={1} {...{ className: joinClasses(styled && "text-text font-semibold") }}>{lane.name}</Text>
        </View>)}
      </View>
      <ScrollView horizontal style={{ flex: 1 }} contentContainerStyle={{ padding: space[1], gap: space[1] }}>
        <View style={{ gap: space[1] }}>
          {lanes.map((lane, li) => <View key={lane.pitch} style={{ flexDirection: "row", gap: space[1] }}>
            {cells[li]!.map((cell, s) => {
              const startTicks = s * stepTicks;
              const playing = s === currentStep;
              const groupShade = Math.floor(s / stepsPerBeat) % 2 === 1;
              const name = `${lane.name}, step ${s + 1}`;
              const cls = joinClasses(styled && "rounded-control items-center justify-center border-2 focus-visible:ring-2 focus-visible:ring-focus active:opacity-80",
                styled && (cell.on
                  ? (cell.accent ? "bg-primary border-primary" : "bg-accent border-accent")
                  : playing ? "bg-surface-raised border-text-muted" : (groupShade ? "bg-surface-sunken border-border" : "bg-surface-raised border-border")));
              const onKeyDown = (e: KeyDownEvent) => {
                if (!cell.on || (e.nativeEvent.key !== "a" && e.nativeEvent.key !== "A")) return;
                e.preventDefault();
                toggleAccent(cell.noteIndex, cell.accent);
              };
              return <Pressable key={s} accessibilityRole="togglebutton" accessibilityLabel={name}
                accessibilityState={{ checked: cell.on, disabled }} {...webToggleProps(cell.on)}
                accessibilityValue={cell.on && cell.accent ? { text: "accented" } : undefined}
                accessibilityActions={cell.on ? [{ name: "accent", label: cell.accent ? "Remove accent" : "Accent" }] : undefined}
                onAccessibilityAction={cell.on ? e => { if (e.nativeEvent.actionName === "accent") toggleAccent(cell.noteIndex, cell.accent); } : undefined}
                disabled={disabled}
                onPress={() => {
                  if (cell.on) void onStepRemove(cell.noteIndex);
                  else void onStepAdd(lane.pitch, startTicks, stepTicks, velocity);
                }}
                onLongPress={cell.on ? () => toggleAccent(cell.noteIndex, cell.accent) : undefined}
                onKeyDown={onKeyDown}
                {...{ className: cls }}
                style={{ width: HIT, height: HIT, opacity: disabled ? opacity[45] : 1 }}>
                {cell.on && cell.accent
                  ? <View pointerEvents="none" {...{ className: joinClasses(styled && "bg-on-primary") }}
                      style={{ width: 10, height: 10, borderRadius: radius[5] }} />
                  : null}
              </Pressable>;
            })}
          </View>)}
        </View>
      </ScrollView>
    </View>
  <ErrorMessage message={actionError??disabledReason} unstyled={unstyled}/></View>;
}

import { Platform } from "react-native";

/**
 * Web semantics for a toggle button. React Native's `togglebutton` role is
 * right on iOS and Android, but React Native Web passes it through as an
 * unknown ARIA role, so browsers and screen readers see no button. On web
 * this returns `role="button"` plus `aria-pressed`, which React Native Web
 * reads ahead of `accessibilityRole`. Native gets nothing, because `role`
 * would override `togglebutton` there too.
 */
export function webToggleProps(pressed: boolean): Record<string, unknown> {
  return Platform.OS === "web" ? { role: "button", "aria-pressed": pressed } : {};
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

